PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS schema_migrations(version INTEGER PRIMARY KEY, applied_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS operators(id TEXT PRIMARY KEY, username TEXT UNIQUE NOT NULL, password_hash TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS operator_sessions(token_hash TEXT PRIMARY KEY, operator_id TEXT NOT NULL REFERENCES operators(id), expires_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS scenarios(id TEXT PRIMARY KEY, version TEXT NOT NULL, seed INTEGER NOT NULL, config_json TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(id TEXT PRIMARY KEY, code TEXT UNIQUE NOT NULL, operator_id TEXT REFERENCES operators(id), scenario_id TEXT NOT NULL REFERENCES scenarios(id), source TEXT NOT NULL, phase TEXT NOT NULL, closed INTEGER NOT NULL DEFAULT 0, parent_id TEXT, rematch_code TEXT, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, expires_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS participants(id TEXT PRIMARY KEY, session_id TEXT NOT NULL REFERENCES sessions(id), role TEXT NOT NULL, alias TEXT NOT NULL, token_hash TEXT UNIQUE NOT NULL, last_seq INTEGER NOT NULL DEFAULT 0, joined_at INTEGER NOT NULL, last_seen INTEGER, UNIQUE(session_id,role));
CREATE TABLE IF NOT EXISTS session_snapshots(session_id TEXT PRIMARY KEY REFERENCES sessions(id), version INTEGER NOT NULL, state_json TEXT NOT NULL, saved_at INTEGER NOT NULL, pause_reason TEXT);
CREATE TABLE IF NOT EXISTS commands(session_id TEXT NOT NULL REFERENCES sessions(id), actor_id TEXT NOT NULL, command_id TEXT NOT NULL, seq INTEGER NOT NULL, kind TEXT NOT NULL, accepted INTEGER NOT NULL, response_json TEXT NOT NULL, created_at INTEGER NOT NULL, PRIMARY KEY(session_id,actor_id,command_id));
CREATE TABLE IF NOT EXISTS events(id INTEGER PRIMARY KEY AUTOINCREMENT, session_id TEXT NOT NULL REFERENCES sessions(id), event_key TEXT NOT NULL, elapsed INTEGER NOT NULL, category TEXT NOT NULL, text TEXT NOT NULL, source TEXT NOT NULL, features_json TEXT NOT NULL, created_at INTEGER NOT NULL, UNIQUE(session_id,event_key));
CREATE TABLE IF NOT EXISTS resource_changes(id INTEGER PRIMARY KEY, session_id TEXT NOT NULL REFERENCES sessions(id), energy_delta INTEGER NOT NULL, items_delta INTEGER NOT NULL, kind TEXT NOT NULL, elapsed INTEGER NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS trial_results(session_id TEXT NOT NULL REFERENCES sessions(id), trial INTEGER NOT NULL, completed_at INTEGER NOT NULL, elapsed INTEGER NOT NULL, PRIMARY KEY(session_id,trial));
CREATE TABLE IF NOT EXISTS encounters(id TEXT PRIMARY KEY, session_id TEXT NOT NULL REFERENCES sessions(id), enemy TEXT NOT NULL, started_elapsed INTEGER NOT NULL, completed_elapsed INTEGER, won INTEGER NOT NULL DEFAULT 0, cycles INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS pokemon_activity(id INTEGER PRIMARY KEY, session_id TEXT NOT NULL REFERENCES sessions(id), event_id INTEGER NOT NULL REFERENCES events(id), category TEXT NOT NULL, details_json TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS clue_events(id INTEGER PRIMARY KEY, session_id TEXT NOT NULL REFERENCES sessions(id), event_id INTEGER NOT NULL REFERENCES events(id), category TEXT NOT NULL, details_json TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS forecasts(id TEXT PRIMARY KEY, session_id TEXT REFERENCES sessions(id), state_version INTEGER NOT NULL, features_json TEXT NOT NULL, result_json TEXT NOT NULL, source TEXT NOT NULL, method_version TEXT NOT NULL, elapsed INTEGER NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS forecast_outcomes(forecast_id TEXT PRIMARY KEY REFERENCES forecasts(id), success INTEGER NOT NULL, actual_remaining INTEGER, observed_elapsed INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS previews(id TEXT PRIMARY KEY, session_id TEXT NOT NULL REFERENCES sessions(id), actor_id TEXT NOT NULL, data_json TEXT NOT NULL, status TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS proposals(id TEXT PRIMARY KEY, session_id TEXT NOT NULL REFERENCES sessions(id), data_json TEXT NOT NULL, status TEXT NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS recommendation_decisions(id INTEGER PRIMARY KEY, session_id TEXT NOT NULL REFERENCES sessions(id), actor_id TEXT NOT NULL, kind TEXT NOT NULL, data_json TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS run_metrics(session_id TEXT PRIMARY KEY REFERENCES sessions(id), source TEXT NOT NULL, success INTEGER NOT NULL, completion_time INTEGER, elapsed INTEGER NOT NULL, metrics_json TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS analytical_versions(id TEXT PRIMARY KEY, method TEXT NOT NULL, dataset_json TEXT NOT NULL, report_json TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS events_session_time ON events(session_id,id);
CREATE INDEX IF NOT EXISTS sessions_owner ON sessions(operator_id,created_at);
CREATE INDEX IF NOT EXISTS forecasts_session ON forecasts(session_id,created_at);
